const openAIResult = $input.first().json;

// Validate the OpenAI response structure
const content = openAIResult?.output?.[0]?.content?.[0]?.text;

if (!content || typeof content !== 'object') {
  throw new Error('OpenAI response is missing structured content');
}

const requiredFields = [
  'blog_title',
  'meta_title',
  'meta_description',
  'html',
  'faq_schema'
];

for (const field of requiredFields) {
  if (typeof content[field] !== 'string' || !content[field].trim()) {
    throw new Error(`OpenAI response is missing required field: ${field}`);
  }
}

// Reuse the already-validated YouTube data
const youtubeUrl = $('Edit Fields').first().json.youtube_url;
const videoId = $('Parse YouTube URL').first().json.youtube_video_id;

if (!videoId) {
  throw new Error('Validated YouTube video ID is missing');
}

// Build the embed HTML from the validated ID
const youtubeEmbed = `<div class="youtube-embed">
  <iframe
    width="560"
    height="315"
    src="https://www.youtube.com/embed/${videoId}"
    title="YouTube video player"
    frameborder="0"
    allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
    allowfullscreen>
  </iframe>
</div>`;

// Add the embed to the beginning of the blog HTML
const finalHtml = youtubeEmbed + content.html;

return [
  {
    json: {
      blog_title: content.blog_title,
      meta_title: content.meta_title,
      meta_description: content.meta_description,
      html: finalHtml,
      faq_schema: content.faq_schema,
      youtube_url: youtubeUrl
    }
  }
];

